import OpenAI from "openai";

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const client = new OpenAI({
      apiKey: env.OPENAI_API_KEY,
      baseURL: `https://gateway.ai.cloudflare.com/v1/${env.ACCOUNT_ID}/support/openai`,
    });
    const reply = await client.chat.completions.create({ model: "gpt-4o-mini", messages: [{ role: "user", content: await request.text() }] });
    return new Response(reply.choices[0].message.content);
  },
};

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const text = await request.text();
    const result = await env.AI.run("@cf/meta/llama-3.1-8b-instruct", {
      prompt: `Suggest three tags for: ${text}`,
    });
    return Response.json(result);
  },
};

